    grammar: { title: 'Um … zu …: для какой цели?', explanation: 'Если исполнитель основного и целевого действия один, цель можно выразить конструкцией um … zu + Infinitiv. Весь оборот отделяется запятой.', pattern: 'Hauptsatz, um + Ergänzungen + zu + Infinitiv.', examples: [{ de: 'Wir vernetzen die Maschinen, um Produktionsdaten zu sammeln.', ru: 'Мы объединяем машины в сеть, чтобы собирать производственные данные.' }, { de: 'Die Bank nutzt Software, um Zahlungen zu prüfen.', ru: 'Банк использует ПО, чтобы проверять платежи.' }], tip: 'Bei trennbaren Verben: um die Anlage einzuschalten. Zu помещается между приставкой и основой.' },
    diagram: { type: 'compare', nodes: [{ label: 'Kommunikation', detail: 'Сети и передача сообщений' }, { label: 'Unterhaltung', detail: 'Игры, видео и звук' }, { label: 'Business', detail: 'Финансы, торговля и ERP' }, { label: 'Industrie', detail: 'Машины, производство и Supply Chain' }] },
