    writing: { prompt: 'Вы выпускаете обновление. В 2–3 предложениях расскажите о программе, библиотеке и исправлении ошибки.', required: [{ stem: 'software', label: 'Software' }, { stem: 'bibliothek', label: 'Bibliothek' }, { stem: 'fehler', label: 'Fehler' }], model: 'Unsere Software verwendet eine Bibliothek für die Datenverarbeitung. Wir testen die neue Version und beheben einen Fehler.', translation: 'Наше ПО использует библиотеку для обработки данных. Мы тестируем новую версию и устраняем ошибку.', checklist: ['Библиотека имеет понятное назначение', 'Описано действие по исправлению ошибки', 'Использованы все три термина'] },
